1	// Reactive taxonomy hook: fetches squads + tag categories from the server,
2	// auto-refetches on `taxonomy:update` SSE events. Single source of truth for
3	// every UI that needs the live squad/tag list.
4	
5	import { useEffect, useState, useCallback } from 'react'
6	import { getTaxonomy, subscribeOrgChart, type TaxonomyData, type SquadDef, type TagCategoryDef } from '../lib/api'
7	import { SQUADS as FALLBACK_SQUADS, TAG_TAXONOMY as FALLBACK_TAGS } from '../lib/orgConstants'
8	
9	// Static fallback so UI still renders if API offline (degraded but functional).
10	function fallback(): TaxonomyData {
11	  const cats: Record<string, TagCategoryDef> = {}
12	  for (const [k, v] of Object.entries(FALLBACK_TAGS)) {
13	    cats[k] = {
14	      label: v.label,
15	      tags: Object.fromEntries(v.tags.map(t => [t, { label: t }])),
16	    }
17	  }
18	  return {
19	    squads: FALLBACK_SQUADS.map(s => ({ ...s, description: s.description })),
20	    categories: cats,
21	  }
22	}
23	
24	const PILL_STYLES: Record<string, { pill: string; pillActive: string }> = {
25	  tech: {
26	    pill: 'bg-blue-500/12 text-blue-400 border border-blue-500/25 hover:bg-blue-500/20',
27	    pillActive: 'bg-blue-500 text-white border border-blue-500',
28	  },
29	  'work-type': {
30	    pill: 'bg-purple-500/12 text-purple-400 border border-purple-500/25 hover:bg-purple-500/20',
31	    pillActive: 'bg-purple-500 text-white border border-purple-500',
32	  },
33	  domain: {
34	    pill: 'bg-emerald-500/12 text-emerald-400 border border-emerald-500/25 hover:bg-emerald-500/20',
35	    pillActive: 'bg-emerald-500 text-white border border-emerald-500',
36	  },
37	}
38	
39	export function pillStyleFor(category: string): { pill: string; pillActive: string } {
40	  return PILL_STYLES[category] || PILL_STYLES.tech
41	}
42	
43	export interface UseTaxonomyResult {
44	  squads: SquadDef[]
45	  squadById: Record<string, SquadDef>
46	  categories: Record<string, TagCategoryDef>
47	  /** Convenience array helpers per category. */
48	  tagsIn: (category: string) => string[]
49	  loading: boolean
50	  refetch: () => void
51	}
52	
53	let _cache: TaxonomyData | null = null
54	const _listeners = new Set<(d: TaxonomyData) => void>()
55	let _inflight: Promise<TaxonomyData> | null = null
56	
57	async function fetchAndBroadcast() {
58	  if (_inflight) return _inflight
59	  _inflight = getTaxonomy()
60	    .then(data => {
61	      _cache = data
62	      _listeners.forEach(fn => fn(data))
63	      return data
64	    })
65	    .catch(() => {
66	      const fb = fallback()
67	      _cache = fb
68	      _listeners.forEach(fn => fn(fb))
69	      return fb
70	    })
71	    .finally(() => { _inflight = null })
72	  return _inflight
73	}
74	
75	export function useTaxonomy(): UseTaxonomyResult {
76	  const [data, setData] = useState<TaxonomyData>(() => _cache || fallback())
77	  const [loading, setLoading] = useState(!_cache)
78	
79	  useEffect(() => {
80	    const onChange = (d: TaxonomyData) => { setData(d); setLoading(false) }
81	    _listeners.add(onChange)
82	    if (!_cache) {
83	      fetchAndBroadcast().finally(() => setLoading(false))
84	    } else {
85	      setLoading(false)
86	    }
87	    return () => { _listeners.delete(onChange) }
88	  }, [])
89	
90	  // Subscribe to SSE so any taxonomy:update across pages auto-refetches
91	  useEffect(() => {
92	    const es = subscribeOrgChart((ev) => {
93	      if (ev.type === 'taxonomy:update') {
94	        fetchAndBroadcast()
95	      }
96	    })
97	    return () => es.close()
98	  }, [])
99	
100	  const refetch = useCallback(() => { fetchAndBroadcast() }, [])
101	
102	  const squadById = Object.fromEntries(data.squads.map(s => [s.id, s]))
103	  const tagsIn = useCallback(
104	    (category: string) => Object.keys(data.categories?.[category]?.tags || {}),
105	    [data]
106	  )
107	
108	  return {
109	    squads: data.squads,
110	    squadById,
111	    categories: data.categories,
112	    tagsIn,
113	    loading,
114	    refetch,
115	  }
116	}
